INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 6, 'theory', 'Квиз: cgroups v2');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 6, 0, 'Как проверить, что хост работает на cgroup v2?', '["cat /proc/version", "mount | grep tmpfs", "systemctl is-system-running", "stat -fc %T /sys/fs/cgroup и получить cgroup2fs"]', 3, 'Тип файловой системы каталога /sys/fs/cgroup говорит о версии: cgroup2fs для второй, tmpfs для первой (там под ним смонтированы отдельные деревья контроллеров).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 6, 1, 'Запись +memory в cgroup.subtree_control группы /a/b отклоняется, хотя memory есть в её cgroup.controllers. Что проверить?', '["В группе /a/b есть собственные процессы", "Размер swap на хосте", "Включён ли memory в корне ещё раз", "Версия systemd"]', 0, 'Не корневая группа раздаёт ресурсы потомкам, только если в ней самой нет процессов. Контроллер у /a/b уже доступен, раз он в её controllers, поэтому дело в правиле отсутствия внутренних процессов.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 6, 2, 'Что означает значение «200000 100000» в cpu.max?', '["Вес 200 вместо 100", "Квота 100 мс за период 200 мс, то есть полпроцессора", "Группа может использовать до двух процессоров", "Не более 200000 процессов"]', 2, 'Первое число — квота, второе — период, оба в микросекундах. Отношение 200000 к 100000 равно двум процессорам. Вес задаётся другим файлом, cpu.weight.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 6, 3, 'Чем memory.high отличается от memory.max?', '["Они равнозначны", "high притормаживает группу и отбирает память без OOM-киллера; max при невозможности освободить память запускает OOM-киллер в группе", "high жёсткий предел, а max мягкий", "high действует только на swap"]', 1, 'При превышении high процессы замедляют и заставляют освобождать память, но убийство не запускается. memory.max — жёсткая граница: если память освободить нельзя, OOM-киллер работает внутри группы.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 6, 4, 'У слайса MemoryMax=2G, у службы внутри него MemoryMax=10G. Какой предел действует на службу?', '["10G, потому что он ближе к службе", "12G, пределы суммируются", "2G, причём общие со всем слайсом", "Служба не ограничена"]', 2, 'Действует самый строгий предел на пути к корню, а память слайса делят все его потомки. Систем-ди показывает итог в свойстве EffectiveMemoryMax.');
